mapper.select:
SELECT COALESCE(MAX(version_no), 0)
FROM t_quote_version
WHERE quote_id = #{quoteId}

mapper.insert:
INSERT INTO t_quote_version (
    quote_id, version_no, valid_until, total_amount, remark, create_time, create_by
) VALUES (
    #{quoteId}, #{versionNo}, #{validUntil}, #{totalAmount}, #{remark}, #{createTime}, #{createBy}
)

mapper.update:
UPDATE t_quote_version
SET valid_until = #{validUntil},
    total_amount = #{totalAmount},
    remark = #{remark},
    create_time = #{createTime},
    create_by = #{createBy}
WHERE id = #{id}
  AND quote_id = #{quoteId}
